            Exercise.MultipleChoice(id = "roughgarden_ag2013_s12_e02", prompt = "Si μ passe à 12 et λ reste 8, quel est le délai ?", options = listOf("1/4", "1/2", "4", "1/12"), correctOptionIndex = 0, explanation = "Après hausse de capacité, le délai est 1/(12−8)=1/4. L’écart capacité-charge passe de 2 à 4, ce qui divise le délai calculé par deux selon cette fonction.", hint = "Réapplique 1/(μ−λ)."),
            Exercise.MultipleChoice(id = "roughgarden_ag2013_s12_e03", prompt = "Dans le modèle atomique affine de cette séance, une instance a un coût optimal de 4 et un pire équilibre de coût 10. Quel est son prix de l’anarchie ?", options = listOf("5/2", "4/3", "2", "3"), correctOptionIndex = 0, explanation = "Le rapport porte sur la même instance et le même trafic : 10/4=5/2. Ici chaque joueur déplace une unité entière; il s’agit du modèle atomique affine. Cette instance atteint sa borne serrée, distincte de la borne non atomique 4/3 de la séance précédente. Cela ne signifie pas que chaque instance atomique atteint 5/2.", hint = "Divise le coût du pire équilibre par le coût optimal; identifie le modèle avant de comparer les bornes.")
        ),
        objective = "Calculer le délai avec capacité accrue et distinguer les modèles de routage.",
        learningNotes = "La première partie étudie le surdimensionnement en routage non atomique. Pour une file `M/M/1`, le délai d’une arête de capacité u et de charge x est 1/(u−x), lorsque x<u. Augmenter la capacité éloigne le réseau de la saturation. Le théorème de la séance garantit que le coût d’un flux d’équilibre de taux r est au plus celui d’un flux optimal de taux 2r. La deuxième partie change de modèle : dans le routage atomique, il y a k joueurs finis, chacun contrôlant une unité de trafic et choisissant seul un chemin. Une déviation ajoute une unité à la charge des arêtes nouvellement empruntées. Pour les coûts affines c_e(x)=a_e x+b_e avec a_e,b_e≥0, le théorème 2.1 prouve une borne POA de 5/2, atteinte dans l’exemple à quatre joueurs (coût optimal 4, pire équilibre 10). Cette borne atomique 5/2 est distincte de la borne non atomique 4/3 démontrée la séance précédente.",
        sourceUrls = listOf("https://timroughgarden.org/f13/l/l12.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 12,
        sourceTitle = "Network Over-Provisioning",
        sessionKind = "lesson"
    )

