            Exercise.MultipleChoice(id = "roughgarden_ag2013_s13_e02", prompt = "Quel concept interdit une déviation unilatérale profitable du profil pur ?", options = listOf("Nash pur", "Équilibre corrélé", "CCE seulement", "Minimax"), correctOptionIndex = 0, explanation = "Un Nash pur est un profil déterministe où aucun joueur ne peut réduire seul son coût en changeant d’action, les choix adverses restant fixes. CE et CCE portent plutôt sur des distributions ou recommandations et n’exigent pas que chaque profil observé soit un Nash pur.", hint = "Il porte sur le profil courant et une déviation individuelle.")
        ),
        objective = "Vérifier un Nash pur et différencier les principaux concepts d’équilibre.",
        learningNotes = "Le potentiel de Rosenthal somme, sur chaque ressource, les coûts marginaux de ses utilisateurs successifs. Une déviation profitable réduit ce potentiel. Un minimum local est donc un équilibre pur. La hiérarchie distingue Nash pur, Nash mixte, équilibre corrélé et CCE : le type de déviation autorisé change. Un Nash pur exclut les améliorations unilatérales depuis le profil observé. Un équilibre corrélé permet une recommandation commune, sans déviation profitable après la recommandation. CCE compare aux actions fixes avant celle-ci.",
        sourceUrls = listOf("https://timroughgarden.org/f13/l/l13.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 13,
        sourceTitle = "Hierarchy of Equilibrium Concepts",
