            Exercise.MultipleChoice(id = "roughgarden_ag2013_s17_e02", prompt = "Ton coût vaut 5 sur 4 tours; une action fixe aurait coûté 3. Regret moyen ?", options = listOf("1/2", "2", "1/4", "8"), correctOptionIndex = 0, explanation = "Le meilleur comparateur fixe coûte 3. Le regret cumulé est 5−3=2; divisé par les 4 tours, cela donne 2/4=1/2. Ce calcul compare à une action constante, pas au meilleur choix différent à chaque tour.", hint = "\$\\frac{\\text{coût joué}-\\text{coût fixe}}{\\text{nombre de tours}}\$.")
        ),
        objective = "Calculer le regret externe et relier apprentissage à l’équilibre CCE.",
        learningNotes = "Le regret externe compare le coût cumulé à la meilleure action fixe rétrospectivement, pas au meilleur choix différent à chaque tour. Les poids multiplicatifs augmentent le poids des actions peu coûteuses et obtiennent un regret moyen décroissant comme √(log n/T) pour des coûts bornés. Si chaque joueur a peu de regret externe, l’historique moyen approche un équilibre corrélé grossier, pas nécessairement Nash. Le modèle suppose l’observation du vecteur de coût complet.",
        sourceUrls = listOf("https://timroughgarden.org/f13/l/l17.pdf"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 17,
        sourceTitle = "No-Regret Dynamics",
        sessionKind = "lesson"
    )

