            Exercise.MultipleChoice(id = "roughgarden_ag2013_s19_e02", prompt = "Parmi 16 solutions, combien au plus peuvent être visitées sous amélioration stricte sans répétition ?", options = listOf("16", "17", "15", "1"), correctOptionIndex = 0, explanation = "Une amélioration stricte empêche de revisiter une solution déjà vue, car son objectif aurait la même valeur qu’avant. Il existe seulement 16 solutions distinctes; la trajectoire peut donc en visiter au plus 16 avant de s’arrêter, sans garantie de polynomialité quand l’espace est grand.", hint = "Une solution répétée rétablirait sa valeur passée.")
